INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-1', 'int-001', 'Mr Lim', '2026-09-12T10:00:00+08:00'::timestamptz, 'The first thing I ask is: is it one zone or many? That single question decides everything else.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-2', 'int-001', 'Mr Lim', '2026-09-12T10:06:00+08:00'::timestamptz, 'If it is one zone, the plant is usually fine. The problem is downstream — a VAV box, a damper, a sensor that has drifted.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-3', 'int-001', 'Mr Lim', '2026-09-12T10:12:00+08:00'::timestamptz, 'People get excited when they see kW/RT climb. But it climbs every afternoon in September. You have to look at the trend over two weeks, not one bad hour.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-4', 'int-001', 'Mr Lim', '2026-09-12T10:18:00+08:00'::timestamptz, 'When one floor complains, I look at that floor, not the plant. Nine times out of ten it is a damper stuck low — the air is there, it just is not reaching the zone.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-5', 'int-001', 'Mr Lim', '2026-09-12T10:24:00+08:00'::timestamptz, 'The day after a public holiday the building starts warm because nobody pre-cooled it. That is not a fault. Do not chase it.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-6', 'int-001', 'Mr Lim', '2026-09-12T10:30:00+08:00'::timestamptz, 'If it is many zones on different facades at the same time, now I look at the plant. That is when re-sequencing the chillers earns its keep.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-7', 'int-001', 'Mr Lim', '2026-09-12T10:36:00+08:00'::timestamptz, 'The mistake I see young engineers make is dropping the whole building setpoint to fix one hot floor. You cool three hundred other zones to fix one. I never do that.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-8', 'int-001', 'Mr Lim', '2026-09-12T10:42:00+08:00'::timestamptz, 'Odour, illness, or anything from the cooling tower — that never goes through me. It goes straight to the duty engineer. Comfort can wait; safety cannot.') ON CONFLICT DO NOTHING;
INSERT INTO transcript_excerpts (id, interview_id, speaker, occurred_at, text) VALUES ('ex-9', 'int-001', 'Mr Lim', '2026-09-12T10:48:00+08:00'::timestamptz, 'I could not tell you the exact tariff band we were on last quarter. I leave the money side to the managers; I just keep the building comfortable and the plant honest.') ON CONFLICT DO NOTHING;
INSERT INTO pills (id, domain, layer, title, owner_id, reviewer_id, status, current_version, access_class) VALUES ('pill-energy-chiller-drift', 'energy'::pill_domain, 'site', 'Zone complaint during plant drift', '22222222-2222-2222-2222-222222222222', '33333333-3333-3333-3333-333333333333', 'approved'::pill_status, 2, 'internal') ON CONFLICT DO NOTHING;
INSERT INTO pill_versions (pill_id, version, status, context, triggers, critical_cues, discounted_signals, decision_logic, never_do, trade_offs, escalation, governance, eval_status, eval_score, created_by) VALUES ('pill-energy-chiller-drift', 1, 'superseded'::pill_status, '{"asset_type": "office", "chiller_plant": "water_cooled_3x", "tariff": "SG_commercial"}'::jsonb, '["Comfort complaint while kW/RT is above baseline", "Single-zone hot complaint"]'::jsonb, '["Repeat complaints from one zone", "One VAV damper stuck low", "kW/RT drift sustained over 10+ days"]'::jsonb, '["One warm afternoon after a public holiday start-up", "Single afternoon spike in kW/RT during September"]'::jsonb, '{"baseline_kwrt": 0.62, "comfort_band_c": [23.0, 25.0], "design_kwrt": 0.6, "drift_threshold": 0.05, "energy_price_sgd_per_kwh": 0.28, "horizon_hours": 24, "lever_recovery": {"opt-inspect-vav": 0.0, "opt-resequence-chillers": 0.7, "opt-setpoint-drop": -0.35}, "load_rt": 850.0}'::jsonb, '["Never lower the building-wide setpoint for a single-zone complaint", "Never re-sequence chillers without approval"]'::jsonb, '{"opt-inspect-vav": "Low effort, no plant energy impact; fixes comfort only.", "opt-resequence-chillers": "Recovers plant efficiency; needs an approved band and a short load shift.", "opt-setpoint-drop": "Fixes the zone but raises plant kWh across every other zone."}'::jsonb, '{"out_of_band_setpoint": "Any setpoint outside the approved band -> escalate.", "safety": "Odour, illness, or any cooling-tower result above limit -> duty engineer before any LLM call."}'::jsonb, '{"note": "Initial capture from int-001.", "owner": "Lim Wei Ming", "reviewer": "Priya Nair"}'::jsonb, 'passed', 0.88, '22222222-2222-2222-2222-222222222222') ON CONFLICT DO NOTHING;
INSERT INTO pill_versions (pill_id, version, status, context, triggers, critical_cues, discounted_signals, decision_logic, never_do, trade_offs, escalation, governance, eval_status, eval_score, created_by) VALUES ('pill-energy-chiller-drift', 2, 'approved'::pill_status, '{"asset_type": "office", "chiller_plant": "water_cooled_3x", "tariff": "SG_commercial"}'::jsonb, '["Comfort complaint while kW/RT is above baseline", "Single-zone hot complaint"]'::jsonb, '["Repeat complaints from one zone", "One VAV damper stuck low", "kW/RT drift sustained over 10+ days"]'::jsonb, '["One warm afternoon after a public holiday start-up", "Single afternoon spike in kW/RT during September"]'::jsonb, '{"baseline_kwrt": 0.62, "comfort_band_c": [23.0, 25.0], "design_kwrt": 0.6, "drift_threshold": 0.05, "energy_price_sgd_per_kwh": 0.28, "horizon_hours": 24, "lever_recovery": {"opt-inspect-vav": 0.0, "opt-resequence-chillers": 0.7, "opt-setpoint-drop": -0.35}, "load_rt": 850.0}'::jsonb, '["Never lower the building-wide setpoint for a single-zone complaint", "Never re-sequence chillers without approval"]'::jsonb, '{"opt-inspect-vav": "Low effort, no plant energy impact; fixes comfort only.", "opt-resequence-chillers": "Recovers plant efficiency; needs an approved band and a short load shift.", "opt-setpoint-drop": "Fixes the zone but raises plant kWh across every other zone."}'::jsonb, '{"out_of_band_setpoint": "Any setpoint outside the approved band -> escalate.", "safety": "Odour, illness, or any cooling-tower result above limit -> duty engineer before any LLM call."}'::jsonb, '{"note": "Tightened damper-first wording after review.", "owner": "Lim Wei Ming", "reviewer": "Priya Nair"}'::jsonb, 'passed', 0.92, '22222222-2222-2222-2222-222222222222') ON CONFLICT DO NOTHING;
INSERT INTO pill_versions (pill_id, version, status, context, triggers, critical_cues, discounted_signals, decision_logic, never_do, trade_offs, escalation, governance, eval_status, eval_score, created_by) VALUES ('pill-energy-chiller-drift', 3, 'draft'::pill_status, '{"asset_type": "office", "chiller_plant": "water_cooled_3x", "tariff": "SG_commercial"}'::jsonb, '["Comfort complaint while kW/RT is above baseline", "Single-zone hot complaint"]'::jsonb, '["Repeat complaints from one zone", "One VAV damper stuck low", "kW/RT drift sustained over 10+ days"]'::jsonb, '["One warm afternoon after a public holiday start-up", "Single afternoon spike in kW/RT during September"]'::jsonb, '{"baseline_kwrt": 0.62, "comfort_band_c": [23.0, 25.0], "design_kwrt": 0.6, "drift_threshold": 0.05, "energy_price_sgd_per_kwh": 0.28, "horizon_hours": 24, "lever_recovery": {"opt-inspect-vav": 0.0, "opt-resequence-chillers": 0.7, "opt-setpoint-drop": -0.35}, "load_rt": 850.0}'::jsonb, '["Never lower the building-wide setpoint for a single-zone complaint", "Never re-sequence chillers without approval"]'::jsonb, '{"opt-inspect-vav": "Low effort, no plant energy impact; fixes comfort only.", "opt-resequence-chillers": "Recovers plant efficiency; needs an approved band and a short load shift.", "opt-setpoint-drop": "Fixes the zone but raises plant kWh across every other zone."}'::jsonb, '{"out_of_band_setpoint": "Any setpoint outside the approved band -> escalate.", "safety": "Odour, illness, or any cooling-tower result above limit -> duty engineer before any LLM call."}'::jsonb, '{"note": "Proposed: allow +0.5C during peak tariff hours. FAILED one comfort case.", "owner": "Lim Wei Ming", "reviewer": "Priya Nair"}'::jsonb, 'failed', 0.71, '22222222-2222-2222-2222-222222222222') ON CONFLICT DO NOTHING;
